		{
			++Index;
			return *this;
		}
		TIndexedContainerIterator operator++(int)
		{
			TIndexedContainerIterator Tmp(*this);
			++Index;
			return Tmp;
		}

		/** Moves iterator to the previous element in the container. */
		TIndexedContainerIterator& operator--()
		{
			--Index;
			return *this;
		}
		TIndexedContainerIterator operator--(int)
		{
			TIndexedContainerIterator Tmp(*this);
			--Index;
			return Tmp;
		}

