		{
			Index += Offset;
			return *this;
		}

		TIndexedContainerIterator operator+(SizeType Offset) const
		{
			TIndexedContainerIterator Tmp(*this);
			return Tmp += Offset;
		}

		TIndexedContainerIterator& operator-=(SizeType Offset)
		{
			return *this += -Offset;
		}

		TIndexedContainerIterator operator-(SizeType Offset) const
		{
			TIndexedContainerIterator Tmp(*this);
			return Tmp -= Offset;
		}

